'use client';
import { Fragment, useEffect, useLayoutEffect, useRef, useState, type MouseEvent, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { Icon } from '../lib/icons';
import { avatarInk } from '../lib/motion';
import '../designme.css';
import './citation-hover-card.css';

export interface CitationHoverCardSource {
  /** One or two letters on the source's coloured mark, like "B" */
  mark: string;
  /** The mark's fill: a colour dark enough for white letters, like '#2f4f9f', or an avatar colour like 'var(--dm-av-b)', which
      brings its own ink */
  color: string;
  /** Where it comes from, like "baymard.com" or "Drive" */
  site: string;
  title: string;
  /** The passage the answer relies on. Wrap the part that matters in <mark> */
  quote: ReactNode;
  /** The quiet line in the corner, like "Read 4 days ago" */
  meta?: string;
  /** Opens in a new tab from the card's link */
  href?: string;
}

export interface CitationHoverCardProps {
  /** The answer. [n] cites source n; a blank line starts a new paragraph */
  text: string;
  sources: CitationHoverCardSource[];
  /** The link in the card's corner */
  openLabel?: string;
  /** Called when the card's link is clicked, with the source and its index */
  onOpenSource?: (source: CitationHoverCardSource, index: number) => void;
  /** Opens a source's card from outside (0 is the first source), or closes it with null. Hover, focus and taps still work */
  open?: number | null;
  /** Called when a card opens or closes, with the source's index, or null */
  onOpenChange?: (index: number | null) => void;
  className?: string;
}

/** the open card: its source, its left edge, the top and bottom of its citation (in the answer's box and on screen), and a key
    that restarts its entrance */
interface Shown { i: number; x: number; top: number; bottom: number; vTop: number; vBottom: number; n: number }

/** An answer with numbered citations. Hovering, focusing or tapping one shows its source in a small card, under the citation
    when it fits there and above it when it doesn't, so the page never cuts it off. */
export function CitationHoverCard({ text, sources, openLabel = 'Open source', onOpenSource, open: openAt, onOpenChange, className }: CitationHoverCardProps) {
  const box = useRef<HTMLDivElement>(null);
  const card = useRef<HTMLDivElement>(null);
  // `at` is the open card; `last` keeps its content while it fades out
  const [at, setAt] = useState<Shown | null>(null);
  const [last, setLast] = useState(0);
  const cur = useRef<number | null>(null);
  const showT = useRef<ReturnType<typeof setTimeout>>(undefined), hideT = useRef<ReturnType<typeof setTimeout>>(undefined);
  // the first citation of each source, which a card opened from outside sits under
  const marks = useRef(new Map<number, HTMLButtonElement>());
  const told = useRef(onOpenChange);
  useEffect(() => { told.current = onOpenChange; });
  // the citation the card belongs to, whether the card should take the focus once it shows (Enter or Space), and whether a
  // focus coming back to the citation (from Escape) should leave the card shut
  const curEl = useRef<HTMLElement | null>(null), focusLink = useRef(false), back = useRef(false);

  const show = (i: number, el: HTMLElement) => {
    clearTimeout(hideT.current); if (cur.current === i) return;
    const b = box.current, c = card.current; if (!b || !c) return;
    const br = b.getBoundingClientRect(), cr = el.getBoundingClientRect();
    const x = Math.max(0, Math.min(cr.left - br.left, br.width - c.offsetWidth));
    cur.current = i; curEl.current = el; setLast(i); told.current?.(i);
    // a new key restarts the entrance, so the card always grows in place instead of sliding across
    setAt(a => ({ i, x, top: cr.top - br.top, bottom: cr.bottom - br.top, vTop: cr.top, vBottom: cr.bottom, n: (a?.n ?? 0) + 1 }));
  };
  const hide = (now = false) => {
    clearTimeout(hideT.current); clearTimeout(showT.current);
    const go = () => { if (cur.current !== null) told.current?.(null); cur.current = null; setAt(a => a && { ...a, i: -1 }); };
    if (now) go(); else hideT.current = setTimeout(go, 140);
  };

  useEffect(() => {
    const down = (e: PointerEvent) => { const t = e.target as Element; if (!card.current?.contains(t) && !t.closest?.('.dm-chx-c')) hide(true); };
    const resize = () => hide(true);
    // Escape puts the card away while the focus or the pointer is on the answer, and leaves the focus where it was, or on
    // its citation when it was in the card
    const key = (e: KeyboardEvent) => { const b = box.current; if (e.key === 'Escape' && cur.current !== null && b && (b.contains(document.activeElement) || b.matches(':hover'))) {
      e.preventDefault(); const to = card.current?.contains(document.activeElement) ? curEl.current : null; hide(true); if (to) { back.current = true; to.focus({ preventScroll: true }); } } };
    document.addEventListener('pointerdown', down); document.addEventListener('keydown', key); addEventListener('resize', resize);
    return () => { document.removeEventListener('pointerdown', down); document.removeEventListener('keydown', key); removeEventListener('resize', resize); clearTimeout(hideT.current); clearTimeout(showT.current); };
  }, []);

  // once it has its content, it goes below its citation when it fits in the window there, and above it when it doesn't and
  // fits above (or has more room there)
  useLayoutEffect(() => {
    const c = card.current; if (!c || !at || at.i < 0) return;
    const h = c.offsetHeight, below = innerHeight - at.vBottom, above = at.vTop;
    const up = below < h + 12 && (above >= h + 12 || above > below);
    c.style.top = (up ? at.top - h - 6 : at.bottom + 6) + 'px';
    c.style.setProperty('--origin', up ? 'bottom left' : 'top left');
  }, [at]);

  // opened with Enter or Space, the card takes the focus on its link once it shows
  useEffect(() => { if (focusLink.current && at && at.i >= 0) { focusLink.current = false; card.current?.querySelector<HTMLElement>('a')?.focus({ preventScroll: true }); } }, [at]);

  // a card opened or closed from outside
  useEffect(() => {
    if (openAt === undefined) return;
    if (openAt === null) { if (cur.current !== null) hide(true); return; }
    const el = marks.current.get(openAt); if (el && cur.current !== openAt) show(openAt, el);
  }, [openAt]); // eslint-disable-line react-hooks/exhaustive-deps

  const cite = (n: number, key: string) => {
    const i = n - 1;
    if (!sources[i]) return <Fragment key={key}>[{n}]</Fragment>;
    return (
      <button type="button" key={key} ref={el => { if (el && !marks.current.has(i)) marks.current.set(i, el); }} className={cx('dm-chx-c', at?.i === i && 'dm-on')} aria-label={`Source ${n}: ${sources[i].title}`}
        onPointerEnter={e => { if (e.pointerType === 'touch') return; const el = e.currentTarget; clearTimeout(showT.current); clearTimeout(hideT.current); showT.current = setTimeout(() => show(i, el), cur.current !== null ? 0 : 90); }}
        onPointerLeave={e => { if (e.pointerType === 'touch') return; clearTimeout(showT.current); hide(); }}
        onFocus={e => { if (back.current) { back.current = false; return; } show(i, e.currentTarget); }} onBlur={e => { if (!card.current?.contains(e.relatedTarget as Node)) hide(); }}
        // touch has no hover: a tap shows the card, the next tap anywhere else hides it. Enter or Space (a click with no
        // pointer) also puts the focus on the card's link, so the keyboard can reach it
        onClick={e => { const key = e.detail === 0; if (cur.current !== i) { focusLink.current = key; show(i, e.currentTarget); } else if (key) card.current?.querySelector<HTMLElement>('a')?.focus({ preventScroll: true }); }}>{n}</button>
    );
  };
  const paragraphs = text.split(/\n\s*\n/).map((p, k) => (
    <p key={k} className="dm-msg dm-chx-p">{p.split(/\[(\d+)\]/).map((part, j) => j % 2 ? cite(+part, k + '-' + j) : part)}</p>
  ));

  const s = sources[at && at.i >= 0 ? at.i : last];
  const open = !!at && at.i >= 0;
  const follow = (e: MouseEvent) => { if (!s?.href) e.preventDefault(); onOpenSource?.(s, sources.indexOf(s)); };
  return (
    <div data-dm="" ref={box} className={cx('dm-chx', className)}>
      {paragraphs}
      <div key={at?.n ?? 0} ref={card} className={cx('dm-chx-card dm-panel', open && 'dm-show')} role="dialog" aria-label="Source"
        style={at ? { left: at.x } : undefined}
        onPointerEnter={() => clearTimeout(hideT.current)} onPointerLeave={e => { if (e.pointerType !== 'touch') hide(); }}
        onBlur={e => { const t = e.relatedTarget as Node | null; if (cur.current !== null && !card.current?.contains(t) && t !== curEl.current) hide(); }}>
        {s && (
          <div className="dm-chx-in">
            <div className="dm-chx-sh"><span className="dm-fv" style={{ background: s.color, color: avatarInk(s.color) }}>{s.mark}</span><span>{s.site}</span></div>
            <div className="dm-chx-t">{s.title}</div>
            <div className="dm-chx-q">{s.quote}</div>
            <div className="dm-chx-f">
              <span>{s.meta}</span>
              <a href={s.href ?? '#'} target={s.href ? '_blank' : undefined} rel="noreferrer" onClick={follow}>{openLabel} <Icon name="ext" size="xs" /></a>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Citation hover card ---------- */
/* an answer with numbered citations; pointing at one (or focusing or tapping it) shows its source in a card that opens over
   the stage from the citation, below it when there is room and above it when there isn't (placePop), so it is never cut off.
   No room is kept for the card under the answer (owner, 17 Nov): the answer sits centred on its own */
.dm-chx{position:relative;overflow:visible}
.dm-chx-p{line-height:1.8}
/* a citation is a small grey number; pointed at or open, it takes the accent tint with the accent's text (owner: highlights
   are the tint, never a solid accent fill) */
.dm-chx-c{display:inline-grid;place-items:center;min-width:18px;height:18px;padding:0 5px;margin:0 1px 0 3px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-hover);color:var(--dm-fg2);font-size:11px;font-variant-numeric:tabular-nums;vertical-align:2px;transition:background .2s,color .2s}
.dm-chx-c.dm-on{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
@media (hover:hover) and (pointer:fine){.dm-chx-c:hover{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}}
/* hidden as well as clear when put away, so Tab never lands on its link; it grows out of its citation's side */
.dm-chx-card{position:absolute;left:0;top:0;width:min(290px,calc(100% - 8px));padding:var(--dm-s-4);opacity:0;visibility:hidden;pointer-events:none;z-index:4;box-shadow:var(--dm-shadow-pop);transform-origin:var(--dm-origin,top left);transition:opacity .16s ease-out,visibility 0s .16s}
.dm-chx-card.dm-show{opacity:1;visibility:visible;pointer-events:auto;animation:dm-chxin .5s var(--dm-ease) both;transition-property:opacity}
@keyframes dm-chxin{from{opacity:0;transform:translateY(10px) scale(.985);filter:blur(3px)}60%{filter:blur(0)}to{opacity:1;transform:none;filter:none}}
.dm-chx-sh{display:flex;align-items:center;gap:var(--dm-s-2);font-size:12px;color:var(--dm-muted)}
/* the source's mark is a vivid fill of its own with white letters (owner, 18 Nov), or an avatar colour with its own ink */
.dm-chx-sh .dm-fv{width:20px;height:20px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));display:grid;place-items:center;font-size:9px;font-weight:500;color:#fff;flex:none}
.dm-chx-t{font-size:13px;font-weight:500;margin:var(--dm-s-2) 0 6px}
/* the passage, with a neutral rule down its left (lines are grey unless they mean something) and the part the answer relies
   on in the accent's tint */
.dm-chx-q{font-size:12.5px;line-height:1.55;color:var(--dm-fg2);padding-left:10px;box-shadow:inset 2px 0 0 var(--dm-faint)}
.dm-chx-q mark{background:var(--dm-sel);color:var(--dm-accent-fg,var(--dm-accent));border-radius:var(--dm-r-tiny,3px);padding:0 2px}
/* the source's foot sits under a hairline in Soft and Blueprint (owner, 21 Nov), 12px from it on each side */
.dm-chx-f{display:flex;align-items:center;justify-content:space-between;margin-top:var(--dm-s-3);padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12px;color:var(--dm-muted)}
/* Clean: the source's foot is the card's off-white foot strip (owner, 21 Nov), its words 16px in */
:root[data-style="clean"] .dm-chx-f,:root [data-style="clean"] .dm-chx-f,:root [data-style="clean"].dm-chx-f{margin:var(--dm-s-3) -16px -16px;padding:calc(var(--dm-strip-y) + 5px) 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card);line-height:18px}
.dm-chx-f a{color:var(--dm-accent-fg,var(--dm-accent));display:inline-flex;align-items:center;gap:var(--dm-s-1);text-decoration:none}
@media (hover:hover) and (pointer:fine){.dm-chx-f a:hover{text-decoration:underline;text-underline-offset:2px}}
/* Clean (owner, 17 and 18 Nov): the card's content 16px from each edge; it scales and fades from its citation like Clean's
   menus, and the source's mark is Clean's neutral grey */
:root[data-style="clean"] .dm-chx-card.dm-show,:root [data-style="clean"] .dm-chx-card.dm-show,:root [data-style="clean"].dm-chx-card.dm-show{animation:dm-chxclean var(--dm-t) var(--dm-ease) both}
@keyframes dm-chxclean{from{opacity:0;transform:scale(.96)}to{opacity:1;transform:none}}
:root[data-style="clean"] .dm-chx-sh .dm-fv,:root [data-style="clean"] .dm-chx-sh .dm-fv,:root [data-style="clean"].dm-chx-sh .dm-fv{background:var(--dm-chip)!important;color:var(--dm-fg2)!important;box-shadow:inset 0 0 0 1px var(--dm-hair)}
